# ❌ ANTI-PATTERN: Unorganized tests missing coverage
def test_search():
    assert search('actor') == ['actor.md']
    assert search('xyz') == []  # Only 2 tests!

# ✅ PATTERN: Categorical organization ensures coverage
class TestSearchCategorical:
    # Category 1: POSITIVE - expected successes
    def test_single_term_match(self):
        assert 'actor.md' in search('actor')

    def test_multi_word_phrase(self):
        assert 'map-feature.md' in search('map feature')

    # Category 2: NEGATIVE - expected failures  
    def test_nonexistent_term(self):
        assert search('nonexistent') == []

    # Category 3: EDGE_CASES - boundaries
    def test_empty_query(self):
        assert search('') == []

    def test_special_characters(self):
        assert search('actor-monitor') == search('actor monitor')

    # Category 4: INTEGRATION - multi-component
    def test_fts_with_file_filters(self):
        results = search('pattern', file_types=['.md'])
        assert all(r.endswith('.md') for r in results)
